-- Hasura-style application schema with event payloads, generated columns, and ignored trigger DDL.
CREATE SCHEMA IF NOT EXISTS app;
CREATE TYPE app.event_status AS ENUM ('queued', 'locked', 'delivered', 'failed');
CREATE TYPE app.delivery_state AS ENUM ('pending', 'ok', 'retry', 'dead');

CREATE TABLE app.customers (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    email TEXT NOT NULL,
    display_name TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT customers_pkey PRIMARY KEY (id),
    CONSTRAINT customers_email_key UNIQUE (email)
);

CREATE TABLE app.orders (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    customer_id UUID NOT NULL,
    order_no TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'draft',
    total_cents INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT orders_pkey PRIMARY KEY (id),
    CONSTRAINT orders_order_no_key UNIQUE (order_no),
    CONSTRAINT orders_customer_fk FOREIGN KEY (customer_id) REFERENCES app.customers(id)
);

CREATE TABLE app.order_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id UUID NOT NULL,
    event_key TEXT GENERATED ALWAYS AS (lower(event_type || ':' || aggregate_id)) STORED,
    aggregate_id UUID NOT NULL,
    event_type TEXT NOT NULL,
    status app.event_status NOT NULL DEFAULT 'queued',
    payload JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT order_events_pkey PRIMARY KEY (id),
    CONSTRAINT order_events_order_fk FOREIGN KEY (order_id) REFERENCES app.orders(id)
);

CREATE TABLE app.event_deliveries (
    event_id BIGINT NOT NULL,
    target_name TEXT NOT NULL,
    state app.delivery_state NOT NULL DEFAULT 'pending',
    attempts INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    delivered_at TIMESTAMPTZ,
    CONSTRAINT event_deliveries_pkey PRIMARY KEY (event_id, target_name),
    CONSTRAINT event_deliveries_event_fk FOREIGN KEY (event_id) REFERENCES app.order_events(id)
);

CREATE INDEX order_events_status_idx ON app.order_events (status, created_at);
CREATE INDEX order_events_payload_idx ON app.order_events USING gin (payload);
CREATE INDEX event_deliveries_state_idx ON app.event_deliveries (state, attempts);
CREATE TRIGGER ignored_hasura_event_trigger AFTER INSERT ON app.orders EXECUTE FUNCTION app.enqueue_event();
